changeSet.sql:
UPDATE da_aip_state SET problem_type = 'METADATA_ERROR', problem_description = CASE WHEN metadata_error_exception IS NULL THEN NULL ELSE 'Chyba při zpracování metadat: ' || metadata_error_exception END WHERE delete_change_id IS NULL AND metadata_error IS TRUE;
UPDATE da_aip_state SET problem_type = 'UNKNOWN_FUND', problem_description = 'Fond nebyl nalezen podle čísla fondu ani podle interního kódu.' WHERE delete_change_id IS NULL AND metadata_error IS NOT TRUE AND fund_id IS NULL;
UPDATE da_aip_state SET problem_type = 'UNKNOWN_INSTITUTION', problem_description = 'Instituce nebyla nalezena.' WHERE delete_change_id IS NULL AND metadata_error IS NOT TRUE AND fund_id IS NOT NULL AND institution_id IS NULL;

UPDATE da_aip_state
   SET problem_detail = metadata_error_exception
 WHERE metadata_error IS TRUE AND metadata_error_exception IS NOT NULL;

DELETE FROM arr_dao_link
 WHERE dao_link_id NOT IN (SELECT dao_link_id FROM arr_legacy_dao_link)
   AND dao_link_id NOT IN (SELECT dao_link_id FROM arr_fs_link);

UPDATE db_hibernate_sequences SET next_val =
    (SELECT coalesce(max(item_spec_declaration_id), 0) + 20 FROM rul_item_spec_declaration)
WHERE sequence_name = 'rul_item_spec_declaration|item_spec_declaration_id';
UPDATE db_hibernate_sequences SET next_val =
    (SELECT coalesce(max(item_spec_assign_declaration_id), 0) + 20 FROM rul_item_spec_assign_declaration)
WHERE sequence_name = 'rul_item_spec_assign_declaration|item_spec_assign_declaration_id';
